/**
 * OAuth state signing and verification.
 *
 * Prevents CSRF attacks on OAuth callbacks by HMAC-signing the state payload
 * with OAUTH_STATE_SECRET. Any tampered or replayed state will fail verification.
 *
 * Usage:
 *   Connect route:  const state = signState({ artist_id, studio_id, ... })
 *   Callback route: const payload = verifyState(stateParam) — throws if invalid
 */

import { createHmac, timingSafeEqual } from 'crypto'

const STATE_TTL_MS = 10 * 60 * 1000 // 10 minutes

function getSecret(): string {
  const secret = process.env.OAUTH_STATE_SECRET
  if (!secret || secret.length < 32) {
    throw new Error('OAUTH_STATE_SECRET must be set and at least 32 characters')
  }
  return secret
}

function hmac(data: string, secret: string): string {
  return createHmac('sha256', secret).update(data).digest('hex')
}

/**
 * Serialises `payload` to a signed, base64url-encoded state string.
 * The payload must be a plain object with string/number/boolean values.
 */
export function signState(payload: Record<string, unknown>): string {
  const secret = getSecret()
  const body = JSON.stringify({ ...payload, ts: Date.now() })
  const encoded = Buffer.from(body).toString('base64url')
  const sig = hmac(encoded, secret)
  return `${encoded}.${sig}`
}

/**
 * Verifies `state` was produced by `signState` and has not expired.
 * Returns the decoded payload on success.
 * Throws an Error on tampered, expired, or malformed state.
 */
export function verifyState(state: string): Record<string, unknown> {
  const secret = getSecret()
  const dotIndex = state.lastIndexOf('.')
  if (dotIndex === -1) throw new Error('oauth_state_malformed')

  const encoded = state.slice(0, dotIndex)
  const receivedSig = state.slice(dotIndex + 1)

  // Timing-safe comparison
  const expectedSig = hmac(encoded, secret)
  const expectedBuf = Buffer.from(expectedSig, 'hex')
  const receivedBuf = Buffer.from(receivedSig, 'hex')
  if (
    receivedBuf.length !== expectedBuf.length ||
    !timingSafeEqual(expectedBuf, receivedBuf)
  ) {
    throw new Error('oauth_state_invalid_signature')
  }

  let payload: unknown
  try {
    payload = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf-8'))
  } catch {
    throw new Error('oauth_state_decode_failed')
  }

  if (typeof payload !== 'object' || payload === null) {
    throw new Error('oauth_state_invalid_shape')
  }

  const p = payload as Record<string, unknown>
  const ts = typeof p['ts'] === 'number' ? p['ts'] : 0
  if (Date.now() - ts > STATE_TTL_MS) {
    throw new Error('oauth_state_expired')
  }

  return p
}

